export async function getAuthenticatedClient() {
  const supabase = await createReadOnlyClient();
  const {
    data: { user },
    error,
  } = await supabase.auth.getUser();

  if (
    error?.name === "AuthSessionMissingError" ||
    error?.status === 401 ||
    (!error && !user)
  ) {
