  const { data: membership, error } = await authenticated.supabase
    .from("memberships")
    .select("role")
    .eq("workspace_id", workspaceId)
    .eq("user_id", authenticated.user.id)
    .maybeSingle();

  if (
    error ||
    !membership ||
    roleRank[membership.role] < roleRank[minimumRole]
  ) {
    return null;
  }

  return authenticated;
}

